/** What a log shows: entries at `level` or above ("" for all) from `component` ("" for all), the latest `lines`. */
/** Which part of a list the daemon pages (files, notifications) to load: from `offset`, at most `limit`, which the
 * daemon takes up to 200. */
export type Page = { offset: number; limit: number };
export type LogQuery = { level: string; component: string; lines: number };
/** A followed log's events: its page (at the start of every connection), then each new matching entry. */
export type LogEvent = { kind: "page"; page: LogPage } | { kind: "entry"; entry: LogEntry };

/** An approval, with `kind: "question"` a question with options, with `kind: "plugin"` a plugin the
 *  agent offers to install, or with `kind: "plugin_setup"` an installed plugin's setup to open (the
 *  plugin comes as the extras list it, `server` or `skill`) (core/events.py). */
export type ApprovalRequest = {
  kind?: string;
  tool?: string;
  reason?: string;
  command?: string;
  question?: string;
  options?: string[];
  multiple?: boolean;
  name?: string;
  server?: FoundServer;
  skill?: FoundSkill;
} & Record<string, unknown>;
export type ApprovalRequired = { type: "ApprovalRequired"; interrupt_id: string; request: ApprovalRequest };
/** An approval's answer, a question's (the options picked, null when skipped), or whether the user
 *  installed the plugin offered. */
export type Decision =
  { approved: boolean; reason: string | null } | { choices: string[] | null } | { installed: boolean } | { done: boolean };

/** The inbox sent the message on to a conversation, `thread_id` (empty: a new one), or the assistant moved
 * work out of it; once the run ends, the client goes there and sends it by `id` (core/events.py). `carried`:
 * the quick exchange in the inbox it followed up, as Markdown, shown before it there ("" for none). */
export type Dispatched = {
  type: "Dispatched";
  id: string;
  thread_id: string;
  title: string;
  text: string;
  line: string;
  carried?: string;
  // A coding task the assistant moved out of the inbox: the agent it's for. It isn't the user's message.
  brief?: string;
};

export type RunEvent =
  | { type: "TextDelta"; text: string }
  // A handed-off agent's reasoning, shown apart from its reply.
  | { type: "Thinking"; text: string }
  // `within`: the id of the delegate call whose subagent made this call; empty for the agent's own.
  | { type: "ToolStarted"; name: string; args: Record<string, unknown>; id?: string; within?: string }
  | { type: "ToolFinished"; name: string; output: string; within?: string }
  // A message the user sent the agent the conversation is handed to while it worked, where it was passed on. `id`: its
  // id in the task's inbox; `waiting`: the agent gets to it only later, which a UserTaken with its id says.
  | { type: "UserSaid"; text: string; files?: string[]; id?: string; waiting?: boolean }
  | { type: "UserTaken"; id: string }
  | ApprovalRequired
  | { type: "Transcribed"; text: string; language: string }
  | Dispatched
  // An update installs: the run was kept, and runs once lo9i is back, announced with this `id` (`held`).
  | { type: "Held"; id: string }
  | { type: "Done" }
  | { type: "Error"; message: string }
  | { type: "Cancelled" };

/** A `run` bus event: a run started by any client or channel. `client_id` is empty for a channel
 * without a client (Telegram). */
/** A `run` bus event. `notice`: for a follow-up the assistant runs on its own, what it follows up on. `brief`: when
 * `text` is a coding task the assistant wrote and not the user, the agent it's for. `held`: for a run kept while an
 * update installed, the id its Held event gave. `resent`: `text` is messages a handed-off agent hadn't got to when
 * its run was stopped or failed, sent to it again. */
export type RunAnnounced = {
  run_id: string;
  thread_id: string;
  channel: string;
  client_id: string;
  text: string;
  notice?: string;
  brief?: string;
  held?: string;
  resent?: boolean;
};

/** A `run_finished` bus event. */
export type RunFinished = { run_id: string; thread_id: string; channel: string; status: string; reply: string };

/** A `sent_on` bus event: a message `client_id` wrote in the inbox (`from_thread_id`) while an update installed,
 * which the daemon sent on after it to `dispatched.thread_id`, where `run_id` runs it (src/assistant/daemon/held.py).
 * That client goes there, as after a Dispatched of its own run. */
export type SentOn = { client_id: string; from_thread_id: string; run_id: string; channel: string; dispatched: Dispatched };

export type BusEvent = { kind: string; data: Record<string, unknown> };

/** A `job` bus event: a scheduled job finished a run. */
export type JobFinished = { name: string; status: string; summary: string };

/** A `background_ended` bus event: background work started in a conversation ended (core/background.py). */
export type BackgroundEnded = { thread_id: string; channel: string; ok: boolean; text: string };

/** An `agent_finished` bus event: the agent a conversation is handed to is done with the user's job and waits for
 * them (core/agent/handoffs.py). `text` is the start of its reply, or what went wrong. */
export type AgentFinished = { thread_id: string; agent: string; ok: boolean; text: string };

/** A `failing` bus event: an MCP server or a skill failed FAILING_AFTER times in a row (core/health.py). */
export type Failing = { area: "mcp" | "skill"; name: string; error: string };

/** A `signed_out` bus event: a remote MCP server's sign-in stopped working (core/health.py). */
export type SignedOut = { name: string; error: string };
